inline const wchar_t* tr(const wchar_t* key){auto found=catalog().find(key);return found==catalog().end()?key:found->second[language];}
inline std::wstring error(const std::string& s){if(s.find("SHA256")!=s.npos||s.find("请选择未修改")!=s.npos)return tr(L"version");if(s.find("Invalid UTF-8")!=s.npos)return tr(L"utf8");if(s.find("Printf placeholders")!=s.npos)return tr(L"placeholders");if(s.find("CSV requires")!=s.npos)return tr(L"csvheader");if(s.find("Duplicate source")!=s.npos)return tr(L"dup");if(s.find("Empty source")!=s.npos)return tr(L"textinvalid");return std::wstring(tr(L"failed"))+L"\n\n"+wide(s);}
inline void loadLanguage(const std::wstring& dir){language=1;try{auto m=JsonParser(readFile(dir+L"\\tools-settings.json")).parse();auto i=m.find(L"language");if(i!=m.end())for(size_t n=0;n<codes.size();++n)if(i->second==codes[n]){language=n;break;}}catch(...){} }
inline void saveLanguage(const std::wstring& dir){save(dir+L"\\tools-settings.json",serialize({{L"language",codes[language]}}));}
